using HRIS.Api.Controllers; using HRIS.Api.DTOs.Declaration; using HRIS.Api.Exceptions; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.Declarations; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly IDeclarationService _service; public IndexModel(IDeclarationService service)=>_service=service; public List<DeclarationTemplateResponseDto> Templates{get;set;}=new(); public List<DeclarationSubmissionResponseDto> Submissions{get;set;}=new(); public bool CanManage{get;set;} public async Task OnGetAsync(){var a=User.ToUserContext();CanManage=a.IsHrOrSupport;Templates=await _service.GetTemplatesAsync();Submissions=await _service.GetSubmissionsAsync(a);} public async Task<IActionResult> OnPostSubmitAsync(int templateId){try{await _service.SubmitAsync(templateId,null,User.ToUserContext());TempData["Success"]="Deklarasi berhasil dicatat.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException){TempData["Error"]=ex.Message;}return RedirectToPage();} public async Task<IActionResult> OnPostSaveTemplateAsync(string title,string content){try{await _service.SaveTemplateAsync(0,new DeclarationTemplateCreateDto{Title=title,Content=content},User.ToUserContext());TempData["Success"]="Template deklarasi disimpan.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException){TempData["Error"]=ex.Message;}return RedirectToPage();} }
